const raw = input || [];

let confirmationRequest = {};
let documents = [];

/*
Le Merge peut retourner :
- un tableau avec le contexte et les résultats MongoDB ;
- un objet fusionné ;
- un tableau contenant directement les créneaux.
*/

if (Array.isArray(raw)) {
  for (const item of raw) {
    if (!item) continue;

    if (item.confirmation_request) {
      confirmationRequest = item.confirmation_request;
    }

    if (Array.isArray(item.documents)) {
      documents = item.documents;
    }

    if (item.slot_id && item.specialty) {
      documents.push(item);
    }
  }
} else {
  confirmationRequest =
    raw.confirmation_request ||
    raw.request ||
    {};

  if (Array.isArray(raw.documents)) {
    documents = raw.documents;
  } else if (raw.slot_id && raw.specialty) {
    documents = [raw];
  }
}

const slot =
  documents.length > 0
    ? documents[0]
    : null;

return {
  confirmation_request: confirmationRequest,

  slot_found: Boolean(slot),

  slot_available:
    Boolean(slot) &&
    slot.status === "available",

  slot: slot
    ? {
        slot_id: slot.slot_id,
        specialty: slot.specialty,
        specialty_label: slot.specialty_label,
        department: slot.department,
        doctor_name: slot.doctor_name,
        date: slot.date,
        start_time: slot.start_time,
        end_time: slot.end_time,
        period: slot.period,
        status: slot.status
      }
    : null
};

const data = input || {};

const slot = data.slot || {};

const confirmationRequest =
  data.confirmation_request ||
  data.request ||
  {};

if (!slot.slot_id) {
  return {
    update_ready: false,
    error: "MISSING_SLOT_ID",
    message: "L'identifiant du créneau est absent.",
    confirmation_request: confirmationRequest
  };
}

const reservedAt = new Date().toISOString();

return {
  update_ready: true,

  confirmation_request: confirmationRequest,

  slot,

  reservation_filter: {
    slot_id: slot.slot_id,
    status: "available"
  },

  reservation_update: {
    status: "reserved",
    reserved_at: reservedAt
  },

  reserved_at: reservedAt
};

const raw = input || {};

const matchedCount =
  raw.matchedCount ??
  raw.matched_count ??
  raw.result?.matchedCount ??
  raw.result?.matched_count ??
  0;

const modifiedCount =
  raw.modifiedCount ??
  raw.modified_count ??
  raw.result?.modifiedCount ??
  raw.result?.modified_count ??
  0;

const reservationSuccessful =
  Number(matchedCount) >= 1 &&
  Number(modifiedCount) >= 1;

return {
  reservation_successful: reservationSuccessful,
  matched_count: Number(matchedCount),
  modified_count: Number(modifiedCount),

  status: reservationSuccessful
    ? "slot_reserved"
    : "slot_conflict",

  message: reservationSuccessful
    ? "Le créneau a été réservé avec succès."
    : "Le créneau n'est plus disponible."
};

const raw = input || [];

let reservationContext = {};
let reservationResult = {};

if (Array.isArray(raw)) {
  for (const item of raw) {
    if (!item) continue;

    if (item.slot && item.reservation_filter) {
      reservationContext = item;
    }

    if (item.reservation_successful !== undefined) {
      reservationResult = item;
    }
  }
} else {
  reservationContext = raw;
  reservationResult = raw;
}

const slot = reservationContext.slot || {};
const confirmationRequest =
  reservationContext.confirmation_request ||
  reservationContext.request ||
  {};

const patient = confirmationRequest.patient || {};

const appointmentId =
  confirmationRequest.appointment_id ||
  `APT-${Date.now()}`;

const document = {
  appointment_id: appointmentId,
  request_id: confirmationRequest.request_id || "",
  slot_id: slot.slot_id || "",

  patient: {
    full_name: patient.full_name || "",
    phone: patient.phone || "",
    email: patient.email || ""
  },

  specialty: slot.specialty || "",
  specialty_label: slot.specialty_label || "",
  department: slot.department || "",
  doctor_name: slot.doctor_name || "",

  appointment_date: slot.date || "",
  start_time: slot.start_time || "",
  end_time: slot.end_time || "",
  period: slot.period || "",

  status: "confirmed",
  reminder_status: "pending",

  reserved_at:
    reservationContext.reserved_at ||
    new Date().toISOString(),

  created_at: new Date().toISOString()
};

return {
  appointment_ready:
    Boolean(document.slot_id) &&
    Boolean(document.patient.full_name) &&
    Boolean(document.patient.phone),

  appointment_document: document
};

const body = input.body || input;

const patient = body.patient || {};
const preferences = body.preferences || body;

return {
  request_id: body.request_id || `REQ-${Date.now()}`,
  source: body.source || "form",

  patient: {
    full_name: patient.full_name?.trim() || "",
    phone: patient.phone?.trim() || "",
    email: patient.email?.trim() || ""
  },

  specialty: preferences.specialty?.toLowerCase().trim() || "",
  preferred_date: preferences.preferred_date || "",
  preferred_period: preferences.preferred_period || "any",

  created_at: new Date().toISOString()
};

const request = input || {};

const errors = [];

const supportedSpecialties = [
  "general_medicine",
  "cardiology",
  "dermatology",
  "radiology"
];

const allowedPeriods = [
  "morning",
  "afternoon",
  "any"
];

// Vérification du nom
if (!request.patient?.full_name) {
  errors.push({
    field: "patient.full_name",
    message: "Le nom complet du patient est obligatoire."
  });
}

// Vérification du téléphone
if (!request.patient?.phone) {
  errors.push({
    field: "patient.phone",
    message: "Le numéro de téléphone est obligatoire."
  });
}

// Vérification de la spécialité
if (!request.specialty) {
  errors.push({
    field: "specialty",
    message: "La spécialité est obligatoire."
  });
} else if (!supportedSpecialties.includes(request.specialty)) {
  errors.push({
    field: "specialty",
    message: "La spécialité sélectionnée n'est pas supportée."
  });
}

// Vérification de la période
if (!allowedPeriods.includes(request.preferred_period)) {
  errors.push({
    field: "preferred_period",
    message: "La période doit être morning, afternoon ou any."
  });
}

// Vérification de la date
if (!request.preferred_date) {
  errors.push({
    field: "preferred_date",
    message: "La date souhaitée est obligatoire."
  });
} else {
  const preferredDate = new Date(
    `${request.preferred_date}T00:00:00`
  );

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  if (Number.isNaN(preferredDate.getTime())) {
    errors.push({
      field: "preferred_date",
      message: "Le format de la date est invalide."
    });
  } else if (preferredDate < today) {
    errors.push({
      field: "preferred_date",
      message: "La date souhaitée ne peut pas être passée."
    });
  }
}

return {
  is_valid: errors.length === 0,
  errors,
  normalized_request: request
};

const raw = input || [];

// MongoDB peut retourner :
// 1. directement un tableau de documents
// 2. un objet contenant la propriété documents
const documents = Array.isArray(raw)
  ? raw
  : Array.isArray(raw.documents)
    ? raw.documents
    : [];

const slots = documents.map((slot) => ({
  slot_id: slot.slot_id,
  specialty: slot.specialty,
  specialty_label: slot.specialty_label,
  department: slot.department,
  doctor_name: slot.doctor_name,
  date: slot.date,
  start_time: slot.start_time,
  end_time: slot.end_time,
  period: slot.period,
  status: slot.status
}));

return {
  success: true,
  slots_found: slots.length > 0,
  status:
    slots.length > 0
      ? "slots_available"
      : "no_exact_slots",
  match_type: "exact",
  count: slots.length,
  message:
    slots.length > 0
      ? "Des créneaux correspondant exactement aux préférences sont disponibles."
      : "Aucun créneau exact n'est disponible.",
  slots
};

const data = input || {};

const request = data.normalized_request || data;

const filter = {
  specialty: request.specialty,
  date: request.preferred_date,
  status: "available"
};

// Si le patient choisit "any", on ne filtre pas par période.
if (
  request.preferred_period &&
  request.preferred_period !== "any"
) {
  filter.period = request.preferred_period;
}

return {
  request,
  mongodb_filter: filter,
  mongodb_sort: {
    start_time: 1
  },
  mongodb_limit: 3
};

const raw = input || [];

let request = {};

// Le Merge retourne un tableau
if (Array.isArray(raw)) {
  const itemWithRequest = raw.find(
    (item) =>
      item &&
      item.request &&
      item.request.specialty &&
      item.request.preferred_date
  );

  request = itemWithRequest?.request || {};
} else {
  request =
    raw.request ||
    raw.normalized_request ||
    {};
}

const specialty = String(request.specialty || "")
  .trim()
  .toLowerCase();

const preferredDate = String(
  request.preferred_date || ""
).trim();

const preferredPeriod = String(
  request.preferred_period || "any"
)
  .trim()
  .toLowerCase();

if (!specialty) {
  return {
    success: false,
    filter_ready: false,
    error: "MISSING_SPECIALTY",
    message: "La spécialité est absente.",
    received_input: raw
  };
}

if (!preferredDate) {
  return {
    success: false,
    filter_ready: false,
    error: "MISSING_PREFERRED_DATE",
    message: "La date souhaitée est absente.",
    received_input: raw
  };
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(preferredDate)) {
  return {
    success: false,
    filter_ready: false,
    error: "INVALID_DATE_FORMAT",
    message: "La date doit respecter le format YYYY-MM-DD.",
    received_date: preferredDate
  };
}

const startDate = new Date(`${preferredDate}T00:00:00Z`);

if (Number.isNaN(startDate.getTime())) {
  return {
    success: false,
    filter_ready: false,
    error: "INVALID_DATE_VALUE",
    message: "La date reçue est invalide.",
    received_date: preferredDate
  };
}

const endDate = new Date(startDate);
endDate.setUTCDate(endDate.getUTCDate() + 7);

const searchStartDate = startDate
  .toISOString()
  .slice(0, 10);

const searchEndDate = endDate
  .toISOString()
  .slice(0, 10);

const alternativeFilter = {
  specialty,
  status: "available",
  date: {
    $gte: searchStartDate,
    $lte: searchEndDate
  }
};

return {
  success: true,
  filter_ready: true,

  request,

  specialty,
  preferred_date: preferredDate,
  preferred_period: preferredPeriod,

  search_start_date: searchStartDate,
  search_end_date: searchEndDate,

  mongodb_filter: alternativeFilter,
  mongodb_filter_json: JSON.stringify(alternativeFilter)
};

const raw = input || {};

const documents = Array.isArray(raw.documents)
  ? raw.documents
  : Array.isArray(raw)
    ? raw
    : [];

// La période demandée peut parfois être perdue après MongoDB.
// Valeur par défaut : any.
const preferredPeriod =
  raw.preferred_period ||
  raw.request?.preferred_period ||
  "any";

const rankedSlots = documents
  .map((slot) => {
    let priority = 3;
    let difference = "Autre créneau disponible";

    if (slot.period === preferredPeriod) {
      priority = 1;
      difference = "Même période, date différente";
    } else if (preferredPeriod === "any") {
      priority = 1;
      difference = "Créneau disponible";
    } else {
      priority = 2;
      difference = "Même spécialité, autre période";
    }

    return {
      slot_id: slot.slot_id,
      specialty: slot.specialty,
      specialty_label: slot.specialty_label,
      department: slot.department,
      doctor_name: slot.doctor_name,
      date: slot.date,
      start_time: slot.start_time,
      end_time: slot.end_time,
      period: slot.period,
      status: slot.status,
      difference,
      priority
    };
  })
  .sort((a, b) => {
    if (a.priority !== b.priority) {
      return a.priority - b.priority;
    }

    if (a.date !== b.date) {
      return a.date.localeCompare(b.date);
    }

    return a.start_time.localeCompare(b.start_time);
  })
  .slice(0, 3)
  .map(({ priority, ...slot }) => slot);

return {
  success: true,
  alternatives_found: rankedSlots.length > 0,
  status:
    rankedSlots.length > 0
      ? "alternative_slots_available"
      : "no_slots_available",
  match_type: "alternative",
  count: rankedSlots.length,
  message:
    rankedSlots.length > 0
      ? "Aucun créneau exact n'est disponible. Voici les meilleures alternatives."
      : "Aucun créneau disponible n'a été trouvé pour cette spécialité.",
  slots: rankedSlots
};

return {
  success: false,
  status: "no_slots_available",
  match_type: "none",
  count: 0,
  message:
    "Aucun créneau disponible n'a été trouvé pour cette spécialité dans les 7 prochains jours.",
  slots: []
};

const raw = input || [];

let appointmentContext = {};
let insertionResult = {};

if (Array.isArray(raw)) {
  for (const item of raw) {
    if (!item) continue;

    if (item.appointment_document) {
      appointmentContext = item;
    }

    if (
      item.acknowledged !== undefined ||
      item.insertedId ||
      item.inserted_id
    ) {
      insertionResult = item;
    }
  }
} else {
  appointmentContext = raw;
  insertionResult = raw;
}

const appointment =
  appointmentContext.appointment_document || {};

const insertedId =
  insertionResult.insertedId ||
  insertionResult.inserted_id ||
  null;

const insertionSuccessful =
  insertionResult.acknowledged === true ||
  Boolean(insertedId);

if (!insertionSuccessful) {
  return {
    success: false,
    status: "appointment_creation_failed",
    message:
      "Le créneau a été réservé, mais le rendez-vous n'a pas pu être enregistré.",
    appointment: null
  };
}

return {
  success: true,
  status: "appointment_confirmed",
  message: "Votre rendez-vous a été confirmé avec succès.",

  appointment: {
    appointment_id: appointment.appointment_id,
    request_id: appointment.request_id,
    slot_id: appointment.slot_id,

    patient: appointment.patient,

    specialty: appointment.specialty,
    specialty_label: appointment.specialty_label,
    department: appointment.department,
    doctor_name: appointment.doctor_name,

    date: appointment.appointment_date,
    start_time: appointment.start_time,
    end_time: appointment.end_time,
    period: appointment.period,

    status: appointment.status,
    reminder_status: appointment.reminder_status
  },

  instructions: [
    "Veuillez vous présenter 15 minutes avant le rendez-vous.",
    "Munissez-vous d'une pièce d'identité.",
    "Apportez vos documents médicaux utiles si nécessaire."
  ],

  reminder_scheduled: true
};

return {
  success: false,
  status: "slot_unavailable",
  code: "SLOT_UNAVAILABLE",
  message:
    "Le créneau sélectionné n'est plus disponible. Veuillez effectuer une nouvelle recherche."
};

const data = input || {};

return {
  success: false,
  status: "validation_error",
  message:
    "Les informations envoyées pour confirmer le rendez-vous sont incomplètes ou invalides.",
  errors: Array.isArray(data.errors)
    ? data.errors
    : []
};

const body = input?.body || input || {};

return {
  source: "text",
  message: String(body.message || "").trim(),
  current_date: new Date().toISOString().slice(0, 10),
  supported_specialties: [
    "general_medicine",
    "cardiology",
    "dermatology",
    "radiology"
  ]
};

const inputData = input || {};

/*
Le parser peut retourner :
1. { parse_success: true, extracted_data: {...} }
2. Directement { intent, patient, preferences, ... }
*/
const extracted =
  inputData.extracted_data &&
  typeof inputData.extracted_data === "object"
    ? inputData.extracted_data
    : inputData;

// Une erreur de parsing explicite doit bloquer la validation.
if (inputData.parse_success === false) {
  return {
    validation_success: false,
    is_complete: false,
    status: "ai_parse_error",
    missing_fields: [],
    errors: [
      {
        field: "ai_output",
        message: "La réponse du modèle n'a pas pu être analysée."
      }
    ],
    extracted_request: null
  };
}

const patient = extracted.patient || {};
const preferences = extracted.preferences || {};

const supportedSpecialties = [
  "general_medicine",
  "cardiology",
  "dermatology",
  "radiology"
];

const allowedPeriods = [
  "morning",
  "afternoon",
  "any"
];

const missingFields = [];
const errors = [];

// Nom
const fullName = String(patient.full_name || "").trim();

if (!fullName) {
  missingFields.push("patient.full_name");
}

// Téléphone
const phone = String(patient.phone || "").trim();

if (!phone) {
  missingFields.push("patient.phone");
}

// Email facultatif
const email = String(patient.email || "").trim();

// Spécialité
const specialty = String(
  preferences.specialty || ""
)
  .trim()
  .toLowerCase();

if (!specialty) {
  missingFields.push("preferences.specialty");
} else if (!supportedSpecialties.includes(specialty)) {
  errors.push({
    field: "preferences.specialty",
    message: "La spécialité extraite n'est pas supportée."
  });
}

// Date
const preferredDate = String(
  preferences.preferred_date || ""
).trim();

if (!preferredDate) {
  missingFields.push("preferences.preferred_date");
} else if (!/^\d{4}-\d{2}-\d{2}$/.test(preferredDate)) {
  errors.push({
    field: "preferences.preferred_date",
    message: "La date doit respecter le format YYYY-MM-DD."
  });
} else {
  const parsedDate = new Date(
    `${preferredDate}T00:00:00Z`
  );

  if (Number.isNaN(parsedDate.getTime())) {
    errors.push({
      field: "preferences.preferred_date",
      message: "La date extraite est invalide."
    });
  }
}

// Période
let preferredPeriod = String(
  preferences.preferred_period || "any"
)
  .trim()
  .toLowerCase();

if (!allowedPeriods.includes(preferredPeriod)) {
  errors.push({
    field: "preferences.preferred_period",
    message:
      "La période doit être morning, afternoon ou any."
  });

  preferredPeriod = "any";
}

const isComplete =
  missingFields.length === 0 &&
  errors.length === 0;

return {
  validation_success: errors.length === 0,
  is_complete: isComplete,

  status: isComplete
    ? "extracted_request_valid"
    : "additional_information_required",

  missing_fields: missingFields,
  errors,

  extracted_request: {
    source: "text",

    patient: {
      full_name: fullName,
      phone,
      email
    },

    preferences: {
      specialty: specialty || null,
      preferred_date: preferredDate || null,
      preferred_period: preferredPeriod
    }
  },

  confidence:
    typeof extracted.confidence === "number"
      ? extracted.confidence
      : null
};

const data = input || {};

const labels = {
  "patient.full_name": "votre nom complet",
  "patient.phone": "votre numéro de téléphone",
  "preferences.specialty": "la spécialité souhaitée",
  "preferences.preferred_date": "la date souhaitée"
};

const questions = (data.missing_fields || []).map((field) => ({
  field,
  question: `Veuillez préciser ${labels[field] || field}.`
}));

return {
  success: false,
  status: "additional_information_required",
  message:
    "J'ai compris une partie de votre demande, mais certaines informations sont manquantes.",
  missing_fields: data.missing_fields || [],
  errors: data.errors || [],
  questions,
  extracted_data: data.extracted_request || null
};

const raw = input || {};

let response = raw;

// Certains nœuds HTTP enveloppent la réponse dans body ou data
if (raw.body !== undefined) {
  response = raw.body;
} else if (raw.data !== undefined) {
  response = raw.data;
}

// Si la réponse est une chaîne JSON
if (typeof response === "string") {
  try {
    response = JSON.parse(response);
  } catch {
    return {
      success: false,
      status: "search_workflow_invalid_response",
      message:
        "Le service de recherche a retourné une réponse invalide.",
      raw_response: response
    };
  }
}

return {
  success: response.success ?? true,
  status: response.status || "search_completed",
  match_type: response.match_type || "none",
  count: Number(response.count || 0),
  message:
    response.message ||
    "La recherche des créneaux est terminée.",
  slots: Array.isArray(response.slots)
    ? response.slots
    : []
};

const data = input || {};

const errors = Array.isArray(data.errors)
  ? data.errors
  : [];

const missingFields = errors.map((error) => error.field);

return {
  success: false,
  status: "validation_error",
  message:
    "La demande de rendez-vous contient des informations manquantes ou invalides.",
  errors,
  missing_fields: missingFields,
  slots: []
};

const body = input?.body || input || {};
const appointment = body.appointment || {};
const patient = appointment.patient || {};

const errors = [];

if (body.status !== "appointment_confirmed") {
  errors.push("Appointment is not confirmed.");
}

if (!appointment.appointment_id) {
  errors.push("Missing appointment_id.");
}

if (!appointment.slot_id) {
  errors.push("Missing slot_id.");
}

if (!patient.full_name) {
  errors.push("Missing patient full name.");
}

if (!patient.email) {
  errors.push("Missing patient email.");
}

return {
  notification_ready: errors.length === 0,
  errors,

  appointment: {
    appointment_id: appointment.appointment_id || "",
    request_id: appointment.request_id || "",
    slot_id: appointment.slot_id || "",

